          ?mmprValue hydrorwth:hasMeanMonthlyPrecip ?meanMonthlyPrecipitationRate .
          FILTER( ?mmprPerMonthValue = ?meanMonthlyPrecipitationRate )
        }
      }
    }
    FILTER(?meanMonthlyPrecipitationRate = ?maxRate)
